// Parity gate (SPEC-01 step 7a): replays tools/parity-{wall,props,cones}.json, generated by
// tools/parity-trace.mjs --scenario from the LIVE DesktopDrift/js/{physics,collision}.js, through
// CarPhysics.StepCar + Collision.ResolveWall/ResolveProps/StepKnockedCone. Orchestration per frame
// mirrors DesktopDrift/js/game-engine.js frame() (lines 405-440). |delta| <= 1e-6 on every value.
#nullable enable
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using NUnit.Framework;

namespace DesktopDrift.Core.Tests
{
    [TestFixture]
    public class ParityScenarioTests
    {
        private const double Tol = 1e-6;

        private sealed class Ctx
        {
            public Dictionary<string, object?> Root = null!;
            public DriveProfile P = null!;
            public PhysicsConstants K = null!;
            public double Dt, Cr, Nose;
            public int Frames;
            public int[] Pattern = null!;
            public int Block;
            public double MaxErr;
            public int Checked;

            public double SteerAt(int i) => Pattern[(i / Block) % Pattern.Length];

            public void Check(double actual, object? expected, string what)
            {
                double e;
                if (expected is bool b) e = b ? 1 : 0;
                else e = (double)expected!;
                double d = Math.Abs(actual - e);
                if (d > MaxErr) MaxErr = d;
                Checked++;
                if (d > Tol) Assert.Fail(what + ": C# " + actual.ToString("R", CultureInfo.InvariantCulture) +
                                         " vs JS " + e.ToString("R", CultureInfo.InvariantCulture));
            }

            public void Report(string name)
            {
                TestContext.WriteLine(name + " parity: " + Checked + " values, max|delta|=" +
                                      MaxErr.ToString("E3", CultureInfo.InvariantCulture));
            }
        }

        private static Dictionary<string, object?> O(object? v) => (Dictionary<string, object?>)v!;
        private static List<object?> A(object? v) => (List<object?>)v!;
        private static double N(object? v) => (double)v!;

        private static Ctx Load(string scenario)
        {
            var root = O(Json.Parse(File.ReadAllText(TestPaths.Locate("tools/parity-" + scenario + ".json"))));
            Assert.AreEqual(scenario, root["scenario"], "scenario");
            Assert.AreEqual("bismark", O(root["source"])["car"], "source.car");
            var drive = O(root["drive"]);
            var kk = O(root["k"]);
            var sp = O(root["steerPattern"]);
            var pat = A(sp["pattern"]);
            var ctx = new Ctx
            {
                Root = root,
                P = new DriveProfile
                {
                    Thrust = N(drive["thrust"]),
                    MaxSpeed = N(drive["maxSpeed"]),
                    Steer = N(drive["steer"]),
                    SteerSmooth = N(drive["steerSmooth"]),
                    LowSpeedTurn = N(drive["lowSpeedTurn"]),
                    SelfAlign = N(drive["selfAlign"]),
                    Grip = N(drive["grip"]),
                    RollFriction = N(drive["rollFriction"]),
                    DriftDrag = N(drive["driftDrag"]),
                    DriftSteerBoost = N(drive["driftSteerBoost"]),
                },
                K = new PhysicsConstants
                {
                    PhysHz = N(kk["PHYS_HZ"]),
                    GripWobble = N(kk["GRIP_WOBBLE"]),
                    SteerWobble = N(kk["STEER_WOBBLE"]),
                },
                Dt = N(root["dt"]),
                Nose = N(root["nose"]),
                Frames = (int)N(root["frameCount"]),
                Block = (int)N(sp["block"]),
                Pattern = new int[pat.Count],
            };
            for (int i = 0; i < pat.Count; i++) ctx.Pattern[i] = (int)N(pat[i]);
            // game-engine.js line 424: CR = M.wid * 0.55 (recomputed here, checked against the JSON).
            ctx.Cr = N(root["wid"]) * 0.55;
            ctx.Check(ctx.Cr, root["cr"], "cr");
            ctx.Check(N(root["len"]) * 0.3, root["nose"], "nose");
            return ctx;
        }

        // game-engine.js lines 424-426: heading, nose offset and the pre-collision capsule snapshot.
        private static Vec2[] Capsule(CarState car, double nose, out double hx, out double hy)
        {
            hx = Math.Cos(car.Angle);
            hy = Math.Sin(car.Angle);
            return new[]
            {
                new Vec2(car.X + hx * nose, car.Y + hy * nose),
                new Vec2(car.X, car.Y),
                new Vec2(car.X - hx * nose, car.Y - hy * nose),
            };
        }

        private static void CheckCar(Ctx ctx, CarState car, List<object?> f, string at)
        {
            ctx.Check(car.X, f[0], at + " x");
            ctx.Check(car.Y, f[1], at + " y");
            ctx.Check(car.Angle, f[2], at + " angle");
            ctx.Check(car.Vx, f[3], at + " vx");
            ctx.Check(car.Vy, f[4], at + " vy");
        }

        [Test]
        public void Wall_RectAndRound_MatchJsWithin1e6()
        {
            var ctx = Load("wall");
            var start = O(ctx.Root["start"]);
            var runs = A(ctx.Root["runs"]);
            Assert.AreEqual(2, runs.Count, "runs");
            foreach (var r in runs)
            {
                var run = O(r);
                var t = O(run["table"]);
                var table = new TableRect { W = N(t["w"]), H = N(t["h"]), Round = (string)t["shape"]! == "round" };
                var frames = A(run["frames"]);
                Assert.AreEqual(ctx.Frames, frames.Count, "frames");
                var car = new CarState { X = N(start["x"]), Y = N(start["y"]), Angle = N(start["angle"]) };
                var sm = new StepMotion();
                for (int i = 0; i < frames.Count; i++)
                {
                    CarPhysics.StepCar(car, sm, ctx.SteerAt(i), ctx.P, ctx.K, ctx.Dt);
                    var body = Capsule(car, ctx.Nose, out double hx, out double hy);
                    double wallHit = Collision.ResolveWall(car, table, ctx.Cr, hx, hy, ctx.Nose, body);
                    var f = A(frames[i]);
                    string at = (string)t["shape"]! + " frame " + i;
                    CheckCar(ctx, car, f, at);
                    ctx.Check(wallHit, f[5], at + " wallHit");
                }
            }
            ctx.Report("wall");
        }

        [Test]
        public void Props_MatchJsWithin1e6()
        {
            var ctx = Load("props");
            var props = new List<Prop>();
            foreach (var po in A(ctx.Root["props"]))
            {
                var o = O(po);
                props.Add(Prop.Prepared(N(o["x"]), N(o["y"]), N(o["ang"]), N(o["hl"]), N(o["r"]), (string)o["kind"]!));
            }
            Assert.AreEqual(4, props.Count, "props");
            var frames = A(ctx.Root["frames"]);
            Assert.AreEqual(ctx.Frames, frames.Count, "frames");
            var car = new CarState();
            var sm = new StepMotion();
            int crashes = 0;
            for (int i = 0; i < frames.Count; i++)
            {
                CarPhysics.StepCar(car, sm, ctx.SteerAt(i), ctx.P, ctx.K, ctx.Dt);
                var body = Capsule(car, ctx.Nose, out _, out _);
                double crash = Collision.ResolveProps(car, props, ctx.Cr, body);
                if (crash > 0) crashes++;
                var f = A(frames[i]);
                CheckCar(ctx, car, f, "frame " + i);
                ctx.Check(crash, f[5], "frame " + i + " crash");
            }
            Assert.Greater(crashes, 0, "the scenario must contain prop impacts");
            ctx.Report("props");
        }

        // Local copy of game-engine.js lines 216-231 (hitConeAt) – arithmetic only; Math.random()
        // is the constant 0.5 of the trace. Step 8 moves the real thing into RaceRules.
        private static void HitConeAt(Cone c, CarState car, double px, double py, double r, double coneR, double random, ref double penalty)
        {
            if (c.Knocked) return;
            double dx = px - c.X, dy = py - c.Y;
            double rr = r + coneR;
            if (dx * dx + dy * dy >= rr * rr) return;
            c.Knocked = true;
            double d = Math.Sqrt(dx * dx + dy * dy);
            if (d == 0) d = 1;
            c.Vx = car.Vx * 0.6 - (dx / d) * 80;
            c.Vy = car.Vy * 0.6 - (dy / d) * 80;
            c.Spin = (random - 0.5) * 18;
            car.Vx *= 0.96; car.Vy *= 0.96;
            penalty += 100;
        }

        [Test]
        public void Cones_MatchJsWithin1e6()
        {
            var ctx = Load("cones");
            double coneR = N(ctx.Root["coneR"]);
            double random = N(ctx.Root["random"]);
            double fAdj = ctx.Dt * ctx.K.PhysHz;
            ctx.Check(fAdj, ctx.Root["fAdj"], "fAdj");
            var cones = new List<Cone>();
            foreach (var co in A(ctx.Root["cones"]))
            {
                var o = O(co);
                cones.Add(new Cone
                {
                    X = N(o["x"]), Y = N(o["y"]), X0 = N(o["x0"]), Y0 = N(o["y0"]),
                    Vx = N(o["vx"]), Vy = N(o["vy"]), Ang = N(o["ang"]), Spin = N(o["spin"]),
                    Knocked = (bool)o["knocked"]!, Ci = (int)N(o["ci"]),
                });
            }
            Assert.AreEqual(6, cones.Count, "cones");
            var noProps = new List<Prop>();
            var frames = A(ctx.Root["frames"]);
            Assert.AreEqual(ctx.Frames, frames.Count, "frames");
            var car = new CarState();
            var sm = new StepMotion();
            double penalty = 0;
            for (int i = 0; i < frames.Count; i++)
            {
                CarPhysics.StepCar(car, sm, ctx.SteerAt(i), ctx.P, ctx.K, ctx.Dt);
                var body = Capsule(car, ctx.Nose, out _, out _);
                foreach (var c in cones)
                {
                    foreach (var p in body) HitConeAt(c, car, p.X, p.Y, ctx.Cr, coneR, random, ref penalty);
                    if (c.Knocked) Collision.StepKnockedCone(c, noProps, coneR, ctx.Dt, fAdj);
                }
                var f = A(frames[i]);
                string at = "frame " + i;
                CheckCar(ctx, car, A(f[0]), at);
                ctx.Check(penalty, f[1], at + " penalty");
                var jc = A(f[2]);
                for (int j = 0; j < cones.Count; j++)
                {
                    var e = A(jc[j]);
                    var c = cones[j];
                    string cat = at + " cone " + j;
                    ctx.Check(c.X, e[0], cat + " x");
                    ctx.Check(c.Y, e[1], cat + " y");
                    ctx.Check(c.Vx, e[2], cat + " vx");
                    ctx.Check(c.Vy, e[3], cat + " vy");
                    ctx.Check(c.Ang, e[4], cat + " ang");
                    ctx.Check(c.Spin, e[5], cat + " spin");
                    ctx.Check(c.Knocked ? 1 : 0, e[6], cat + " knocked");
                }
            }
            Assert.AreEqual(600, penalty, "all six cones must be knocked");
            ctx.Report("cones");
        }
    }
}
